script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var metadata = {};
    var selectedTab = event.payload.selectedTab;
    if (selectedTab == "id=analytics") {
        metadata = {
            level: 'Diagnostics Overview page loaded'
        };
        return {
            event: 'Diagnostics Overview page loaded',
            value: metadata
        };
    } else if (selectedTab == "id=error_log") {
        metadata = {
            level: 'Diagnostics Error Log page loaded'
        };
        return {
            event: 'Diagnostics Error Log page loaded',
            value: metadata
        };
    } else {
        metadata = {
            level: 'Diagnostics Connection status page loaded'
        };
        return {
            event: 'Diagnostics Connection status page loaded',
            value: metadata
        };
    }
}

